"""Display only actual saved Decisions results and the deduplication ledger."""
import json

from .starter import OUTCOMES


def render_analysis(summary, cards, catalog, ledger):
    data = json.dumps({'summary': summary, 'cards': cards, 'catalog': catalog,
                       'ledger': ledger, 'outcomes': OUTCOMES}, ensure_ascii=False, allow_nan=False).replace('<', '\\u003c')
    return TEMPLATE.replace('__DATA__', data)


TEMPLATE = '''<!doctype html><html lang="it"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Decision · primi risultati e registro</title>
<style>:root{color-scheme:light dark;font-family:system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:transparent;color:var(--foreground,light-dark(#222,#eee));font-size:14px;line-height:1.5}.muted{color:var(--muted-foreground,light-dark(#666,#aaa))}.small{font-size:12px}.card{background:var(--card,light-dark(#fafafa,#222));border:1px solid var(--border,light-dark(#ddd,#444));border-radius:var(--radius,12px);padding:16px;margin:12px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.value{font-size:27px;font-weight:650}h2{font-size:17px;margin:0 0 10px}h3{font-size:14px;margin:8px 0}p{margin:7px 0}.chart{height:385px;overflow:auto}.barrow{display:grid;grid-template-columns:65px 1fr 42px;gap:9px;align-items:center;font-size:12px;margin:8px 0}.track{height:15px;background:var(--secondary,light-dark(#eee,#333));border-radius:4px;overflow:hidden}.bar{height:100%;background:var(--chart-1,#9277ee)}.top{background:var(--chart-2,#2eaa8c)}select{font:inherit;color:inherit;background:var(--card,light-dark(#fafafa,#222));border:1px solid var(--border,light-dark(#ddd,#444));padding:8px;border-radius:6px;max-width:100%}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;vertical-align:top;padding:8px;border-bottom:1px solid var(--border,light-dark(#ddd,#444))}th{white-space:nowrap}.note{border-left:3px solid var(--primary,#8062e3);padding-left:12px}details{margin:12px 0}summary{cursor:pointer}.legend{display:flex;gap:12px;flex-wrap:wrap}.stack{display:flex;height:12px;margin-top:9px;border-radius:4px;overflow:hidden}.scroll{background:var(--chart-1,#9277ee)}.glance{background:var(--chart-2,#2eaa8c)}.stop{background:var(--chart-3,#d5a545)}.click{background:var(--chart-4,#df7e91)}@media(max-width:520px){.grid{grid-template-columns:1fr}}</style>
<body><p><b>Reazioni simulate · Gemini Decision 1</b></p><p class="small muted">Quattro profili sintetici congelati, stesso contesto di feed, asset skincare del kit. I punteggi sono probabilità del modello sulle scelte: non CTR misurati, CPM o conversioni.</p><p class="small" id="pending"></p>
<div class="grid"><div class="card"><div class="value" id="assets"></div><span>asset analizzati</span></div><div class="card"><div class="value" id="pairs"></div><span>valutazioni registrate</span></div><div class="card"><div class="value" id="requests"></div><span>richieste API registrate</span></div></div>
<div class="card"><h2>Confronto del segnale di intenzione al click</h2><p class="small muted">Media sui quattro profili con pesi uniformi. Score 0–1, campione tecnico non rappresentativo. Nessuna significatività statistica dimostrata dal ranking.</p><div class="chart" id="ranking"></div></div>
<div class="card"><label for="asset">Esamina un asset</label><p><select id="asset"></select></p><div id="creative"></div><div class="tablewrap" id="people"></div><div class="legend small"><span>scroll = ignora</span><span>glance = occhiata</span><span>stop = si ferma</span><span>click = apre</span></div><div class="stack" id="stack"></div><p class="small muted" id="totals"></p></div>
<div class="card"><h2>Registro e riuso delle analisi</h2><p class="small">Una risposta completata viene riutilizzata quando persona, asset, modello, istruzioni e feed coincidono. Un esito incerto non viene reinviato automaticamente.</p><p class="small" id="last"></p><p class="small" id="usage"></p><details><summary>Stato per persona e asset</summary><div class="tablewrap" id="ledger"></div></details><p class="small note">Il CPM richiede dati di costo/asta e il CTR assoluto richiede calibrazione. Questi risultati servono a esplorare preferenze e frizioni; il collegamento al forecasting non è stato eseguito.</p></div>
<script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=(n,p=3)=>Number(n).toLocaleString('it-IT',{maximumFractionDigits:p});
const ranking=D.summary.ranking;$('assets').textContent=ranking.length;$('pairs').textContent=D.summary.persona_asset_evaluations;$('requests').textContent=D.ledger.requests.length;
$('pending').textContent=(D.summary.asset_states||[]).filter(s=>s.status!=='completed').map(s=>s.asset_id+': '+s.status).join(' · ');
const max=Math.max(.001,...ranking.map(s=>s.click_intent_signal));$('ranking').innerHTML=ranking.map((s,i)=>'<div class="barrow"><span>'+esc(s.asset_id)+'</span><div class="track"><div class="bar '+(!i?'top':'')+'" style="width:'+100*s.click_intent_signal/max+'%"></div></div><span>'+num(s.click_intent_signal)+'</span></div>').join('');
$('asset').replaceChildren(...ranking.map(s=>{const o=document.createElement('option');o.value=s.asset_id;o.textContent=s.asset_id;return o}));
function table(headers,rows){return '<table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function render(){const signal=ranking.find(s=>s.asset_id===$('asset').value);if(!signal)return;const a=D.catalog.creatives.find(a=>a.asset_id===signal.asset_id);$('creative').innerHTML='<h2>'+esc(a.headline)+'</h2><p>'+esc(a.testo_principale)+'</p><p class="muted small">'+esc(a.formato)+' · '+esc(a.leva)+' · '+esc(a.descrizione_visual)+'</p>';$('people').innerHTML=table(['Persona','Scroll','Occhiata','Stop','Click','Scelta e motivo più probabili'],signal.per_person.map(p=>{const card=D.cards.personas.find(c=>c.persona_id===p.persona_id),best=Object.keys(p.probabilities).sort((a,b)=>p.probabilities[b]-p.probabilities[a])[0];return [esc(card?card.name:p.persona_id),num(p.actions.scroll),num(p.actions.glance),num(p.actions.stop),num(p.actions.click),esc(D.outcomes[best]||best)]}));$('stack').innerHTML=Object.entries(signal.actions).map(([action,value])=>'<div class="'+action+'" style="width:'+100*value+'%" title="'+action+': '+num(value)+'"></div>').join('');$('totals').textContent='Attenzione: '+num(signal.attention_signal)+' · intenzione click: '+num(signal.click_intent_signal)+' · score non calibrati.'}
$('asset').addEventListener('change',render);render();
$('last').textContent='Ultimo passaggio: '+D.summary.new_api_requests+' nuove richieste, '+D.summary.reused_questions+' risposte riutilizzate dal registro.';
$('usage').textContent=D.summary.usage_note||'Usage e tempi originali conservati nei file raw e nel registro; nessun costo monetario misurato.';
$('ledger').innerHTML=table(['Asset','Persona','Stato'],D.ledger.analyses.map(a=>[esc(a.asset_id),esc(D.cards.personas.find(c=>c.persona_id===a.persona_id)?.name||a.persona_id),esc(a.status)]));
</script></body></html>'''
